  ('ng-ex11-okemos', 'Gun Turret (1, top, manned)', 125, NULL, 1),
  ('ng-ex11-okemos', 'Turret Camera (1, top)', 10, 'Very small target: Called Shot, -4 to strike.', 2),
  ('ng-ex11-okemos', 'Turret Sensor Array (1, top, bubble shape)', 30, 'Small target: Called Shot, -3 to strike.', 3),
  ('ng-ex11-okemos', 'Spotlights (4)', 6, 'Each. Very small target: Called Shot, -4 to strike.', 4),
  ('ng-ex11-okemos', 'Nose Camera (1)', 10, 'Very small target: Called Shot, -4 to strike.', 5),
  ('ng-ex11-okemos', 'Nose Rail Gun (1)', 75, 'Small target: Called Shot, -3 to strike.', 6),
  ('ng-ex11-okemos', 'Shoulders of Utility Arms (2)', 100, 'Each.', 7),
  ('ng-ex11-okemos', 'Utility Arms and Hands (2)', 50, 'Each. Small target: Called Shot, -3 to strike.', 8),
  ('ng-ex11-okemos', 'Legs and Feet (2)', 190, 'Each.', 9),
  ('ng-ex11-okemos', 'Sleeping Berths (4, Rear Section)', 115, 'Each.', 10),
  ('ng-ex11-okemos', 'Berth Hatches (4)', 50, 'Each.', 11),
  ('ng-ex11-okemos', 'Berth Windows (8)', 15, 'Each, for the glass, plus 40 for its sliding plate.', 12),
  ('ng-ex11-okemos', 'M.D.C. Glass of the Pilot''s Cockpit', 40, 'The text prints 35 twice. Called Shot, -2 to strike.', 13),
  ('ng-ex11-okemos', 'M.D.C. Snap-On Cockpit Plate Covering (Optional)', 100, NULL, 14),
  ('ng-ex11-okemos', 'Main Body', 295, 'The forward section/pilot''s cockpit. Reduced to zero, the vehicle shuts down and is useless.', 15);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-m56-multibot-original', 1, 'Scissor Launchers (2)', 'By missile; any medium-range missile, as a rule armor piercing (2D4x10 M.D.) or high explosive (2D6x10 M.D.)', 1, 'Usually about 40 miles (64 km)', 'One at a time or volleys of 2, 3 or 4', '10, five per launcher', '+1 to strike; guided missiles', 'Assault and anti-fortification, secondarily defense and anti-armor/monsters. Two V-shaped launchers on the back, raised to fire and folded behind the robot when idle; they must be down before the flyer can detach.'),
  ('ng-m56-multibot-original', 2, 'Concealed Shoulder Mini-Missile Launchers (2)', 'By missile; fragmentation (5D6 M.D.) or plasma (1D6x10 M.D.) as a rule', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2 or 3', '18, nine per shoulder', NULL, 'Anti-aircraft and defense, secondarily anti-armor and anti-missile. One launcher behind each flip-out shoulder shield.'),
  ('ng-m56-multibot-original', 3, 'Heavy Ion Cannon', '5D6 M.D. per single blast', 1, '4,000 ft (1,219 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Assault, secondarily defense. A single-barreled gun aimed at ground troops; it faces forward only and tilts through 90 degrees up and down; it goes with the flyer when it detaches.'),
  ('ng-m56-multibot-original', 4, 'NG-101 Light Rail Gun (1)', '6D6 M.D. per 30 round burst', 1, '4,000 ft (1,219 m)', 'Each blast counts as one melee attack', '1,800 rounds (60 bursts)', NULL, 'Assault, secondarily defense. A swivel mount on top of the flying helm, turning 360 degrees and pointing 90 degrees up or down; it needs a gunner at the gun.'),
  ('ng-m57-2n1-megabot', 1, 'Medium-Range Missile Launcher (1)', 'By missile; any medium-range missile, as a rule armor piercing (3D6x10 M.D.) or high explosive (2D6x10 M.D.)', 1, 'Usually about 40+ miles (64+ km)', 'One at a time or volleys of 2, 3 or 4', 'Nine', '+1 to strike', 'Anti-armor, secondarily anti-aircraft. On the left shoulder; stays with the body when the racer detaches.'),
  ('ng-m57-2n1-megabot', 2, 'Short-Range Box Missile Launcher (1)', 'By missile; any short-range missile, as a rule armor piercing (2D6x10 M.D.) or high explosive (2D6x10)', 1, 'Usually about 5 miles (8 km)', 'One at a time or volleys of 2, 4 or 8', '16', '+1 to strike', 'Anti-armor, secondarily anti-aircraft. On the right shoulder; stays with the body when the racer detaches.'),
  ('ng-m57-2n1-megabot', 3, 'Mini-Missile Tube Launchers (8)', 'By missile; fragmentation (5D6 M.D.), armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.) as a rule', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4 or 8', '24, three per tube, reloading itself after each shot', NULL, 'Anti-aircraft and defense, secondarily anti-armor and anti-missile. Four tubes beside each of the racer''s jet thrusters, each turning through a 120 degree arc behind, above and ahead.'),
  ('ng-m57-2n1-megabot', 4, 'NG-IRC57 Heavy Ion Cannon (1)', '1D4x10 M.D. per single blast', 1, '4,000 ft (1,219 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-hovercycle and assault, secondarily anti-personnel and defense. In the racer''s undercarriage. Docked, it points 45 degrees down, fixed forward, good only against troops close to the robot; detached, it becomes the racer''s fixed-forward main gun for long shots, strafing and low dogfights with rocket bikes and power armor.'),
  ('ng-m57-2n1-megabot', 5, 'NG-LC57 Tri-Barrel Heavy Laser Cannon (1)', '3D6 M.D. single, 6D6 M.D. double, 1D6x10 M.D. triple blast', 1, '2,000 ft (610 m)', 'Each single blast or simultaneous double or triple blast at one target counts as one melee attack/action', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily anti-flyer and defense. A turret on the racer, crewed by a gunner or worked remotely from inside, most often a gunner assigned to it or the copilot; 360 degrees with a 90 degree arc up and down.'),
  ('ng-exc17-ogre', 1, 'NG-I17 Medium Ion Cannon (1)', '4D6 M.D. per single blast', 1, '1,800 ft (548.6 m)', 'Single shot only; each shot counts as one melee attack', 'Effectively unlimited', NULL, 'Defense, secondarily assault and anti-personnel. The nose gun, on a turret turning 180 degrees with a 45 degree arc up and down, fired by pilot or copilot; a sensor array on the turret''s right side and a camera on its left sit above the barrel.'),
  ('ng-exc17-ogre', 2, 'NG-732 Pop-Up Mini-Missile Launcher (1, top)', 'By missile; high explosive (1D4x10 M.D.) or plasma (1D6x10 M.D.) as a rule', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3 or 4', '24, with another 24 usually in the cargo hold; reloading takes a trained crewman or Operator 1D4+1 minutes, six more for the untrained', NULL, 'Defense, secondarily anti-armor and anti-aircraft. A low launcher on top near the left shoulder whose cover lifts to fire and drops after; 360 degrees with a 60 degree arc up and down.'),
  ('ng-exc17-ogre', 3, 'Defensive Flare Chaff Launchers: Chaff Flares', 'None. A cloud with a 10% chance per rocket in the volley (60% at most, six rockets) of detonating any missile volley that enters it, the cloud dispersing as it does; flyers caught in it take -6 Perception, -3 initiative, -5 strike, -2 parry and dodge, lose one attack that round, lose optical and laser targeting bonuses and take -20% on Sensory Equipment and Piloting while inside and for the rest of the round', 0, '6,000 ft (1,829 m) straight up', 'One at a time or volleys of 2, 3, 4, 5 or 6', '16 total, two per launcher, per side', NULL, 'Anti-missile, secondarily anti-flyer. Two batteries of four tubes on each side (16 tubes), the first four with chaff rockets that burst at a set altitude or point into sparks, flashes and foil, much like a Flash grenade. Cloud 30 ft across (printed with a 91.4 m conversion), 10 ft (3 m) more per rocket in the volley; it lasts two melee rounds or until spent.'),
  ('ng-exc17-ogre', 4, 'Defensive Flare Chaff Launchers: Conventional Smoke Grenades', 'None; anyone inside the cloud is blind, and nobody outside can see into or through it', 0, '1,200 ft (366 m)', 'One at a time or volleys of 2, 3, 4, 5 or 6', '16 total, two per launcher, per side', NULL, 'Defense, secondarily position marking. The second group of tubes, for blinding monsters and supernatural beings, covering an escape or an attack, or marking a spot. Lasts 1D4+4 minutes, half that in winds of 25 mph (40 km) or more.'),
  ('ng-ex11-okemos', 1, '(Option A) NG-LC117 Heavy Laser Cannon (1)', '4D6 per single blast', 1, '3,000 ft (914 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', '+2 to strike', 'Main Gun Turret (top). Anti-personnel and assault, secondarily defense. Long reach and heavy hitting. Whatever is fitted, the turret needs a gunner, turns 360 degrees with a 45 degree arc up and down, and carries a camera, laser targeting and sensors. 170,000 credits. Printed as 4D6 per blast without a unit.'),
  ('ng-ex11-okemos', 2, '(Option B) NG-IC17 Ion Cannon', '6D6 M.D. per single blast', 1, '1,800 ft (548.6 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', '+1 to strike', 'Main Gun Turret (top). Anti-armor and assault, secondarily anti-personnel and defense. More damage, less range. 120,000 credits.'),
  ('ng-ex11-okemos', 3, '(Option A) Medium NG-217 Rail Gun Turret (1)', '5D6 M.D. per 60 round burst, +4 M.D. within 10 ft (3 m); 1-2 M.D. per round', 1, '2,000 ft (610 m) conventional and silver-coated rounds; 1,000 ft (305 m) weighted wood rounds with silver rings', 'Each single shot or burst counts as one melee attack', '3,000 rounds, 50 bursts', NULL, 'Nose Turret (front). Assault and anti-personnel, secondarily defense. The usual choice for its flexibility: conventional, silver-coated or wood-and-silver rounds (see the Gunwolf) against animals, monsters and the supernatural. Whatever is fitted, the nose mount sweeps 180 degrees forward with a 45 degree arc up and down. 125,000 credits.'),
  ('ng-ex11-okemos', 4, '(Option B) NG-017 Heavy Machine-Gun (1)', 'Short burst of 2-5 rounds 2D4x10 S.D.C.; 20 round burst 4D6x10 S.D.C./1 M.D.; 40 round burst 1D6x100 S.D.C./1D6 M.D. equivalent', 0, '3,000 ft (614 m) conventional and silver-coated rounds; 1,000 ft (305 m) weighted wood rounds with silver rings', 'Burst fire only; each burst counts as one melee attack', '4,800 rounds, 120 long bursts', NULL, 'Nose Turret (front). Assault and anti-personnel, secondarily defense. An S.D.C. gun with a huge payload, for soft targets and, with silver rounds, supernatural and magic foes; weak against M.D.C. 60,000 credits. The range is printed with a 614 m conversion.'),
  ('ng-ex11-okemos', 5, '(Option C) NG-127 Laser (1)', '4D6 M.D. per simultaneous triple blast', 1, '2,000 ft (610 m)', 'Each triple blast counts as one melee attack', 'Effectively unlimited', NULL, 'Nose Turret (front). Anti-personnel and assault, secondarily defense. A medium laser with reach and no ammunition to run out of. 140,000 credits.'),
  ('ng-ex11-okemos', 6, '(Option D) Box Mini-Missile Launcher (1)', 'By missile; fragmentation (5D6 M.D.) or plasma (1D6x10 M.D.) as a rule', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3 or 4', '12', NULL, 'Nose Turret (front). Anti-armor and anti-missile, secondarily anti-personnel and defense. Replaces the nose gun. 100,000 credits plus the missiles, usually 1,200-2,500 credits each by type (Rifts Ultimate Edition p.257).');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-m56-multibot-original', 'ng-m57-2n1-megabot', 'ng-exc17-ogre', 'ng-ex11-okemos');
SELECT 'their 71 locations are in' AS assertion, count(*) AS got, 71 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-m56-multibot-original', 'ng-m57-2n1-megabot', 'ng-exc17-ogre', 'ng-ex11-okemos');
SELECT 'their 19 weapon entries are in' AS assertion, count(*) AS got, 19 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-m56-multibot-original', 'ng-m57-2n1-megabot', 'ng-exc17-ogre', 'ng-ex11-okemos');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-m56-multibot-original', 'ng-m57-2n1-megabot', 'ng-exc17-ogre', 'ng-ex11-okemos') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

